  'Versatile directory engine adaptable for Schools, Housing Societies, Hospitals, SaaS & Corporate entities with extensible custom attributes.': {
    "en": "Versatile directory engine adaptable for Schools, Housing Societies, Hospitals, SaaS & Corporate entities with extensible custom attributes.",
    "hi": "स्कूलों, हाउसिंग सोसायटियों, अस्पतालों, SaaS और कॉर्पोरेट संस्थाओं के लिए अनुकूलनीय बहुमुखी निर्देशिका इंजन।",
    "bn": "স্কুল, হাউজিং সোসাইটি, হাসপাতাল, SaaS এবং কর্পোরেট প্রতিষ্ঠানের জন্য নমনীয় ডিরেক্টরি ইঞ্জিন।",
    "te": "పాఠశాలలు, హౌసింగ్ సొసైటీలు, ఆసుపత్రులు, SaaS మరియు కార్పొరేట్ సంస్థల కోసం అనుకూలమైన డైరెక్టరీ ఇంజిన్.",
    "mr": "शाळा, गृहनिर्माण संस्था, रुग्णालये, SaaS आणि कॉर्पोरेट संस्थांसाठी लवचिक निर्देशिका प्रणाली.",
    "ta": "பள்ளிகள், வீட்டு வசதி சங்கங்கள், மருத்துவமனைகள், சாஸ் மற்றும் நிறுவனங்களுக்கான டைரக்டரி என்ஜின்.",
    "gu": "શાળાઓ, હાઉસિંગ સોસાયટીઓ, હોસ્પિટલો, SaaS અને કોર્પોરેટ સંસ્થાઓ માટે અનુકૂળ ડિરેક્ટરી એન્જિન.",
    "kn": "ಶಾಲೆಗಳು, ಹೌಸಿಂಗ್ ಸೊಸೈಟಿಗಳು, ಆಸ್ಪತ್ರೆಗಳು, SaaS ಮತ್ತು ಕಾರ್ಪೊರೇಟ್ ಘಟಕಗಳಿಗಾಗಿ ಹೊಂದಿಕೊಳ್ಳುವ ಡೈರೆಕ್ಟರಿ ಎಂಜಿನ್.",
    "ml": "സ്കൂളുകൾ, ഹൗസിംഗ് സൊസൈറ്റികൾ, ആശുപത്രികൾ, സാസ്, കോർപ്പറേറ്റ് സ്ഥാപനങ്ങൾ എന്നിവയ്ക്കായുള്ള ഡയറക്ടറി എഞ്ചിൻ.",
    "pa": "ਸਕੂਲਾਂ, ਹਾਊਸਿੰਗ ਸੁਸਾਇਟੀਆਂ, ਹਸਪਤਾਲਾਂ, SaaS ਅਤੇ ਕਾਰਪੋਰੇਟ ਸੰਸਥਾਵਾਂ ਲਈ ਅਨੁਕੂਲ ਡਾਇਰੈਕਟਰੀ ਇੰਜਣ।",
    "or": "ବିଦ୍ୟାଳୟ, ଗୃହ ନିର୍ମାଣ ସମିତି, ଡାକ୍ତରଖାନା, SaaS ଏବଂ କର୍ପୋରେଟ୍ ସଂସ୍ଥା ପାଇଁ ନମନୀୟ ଡିରେକ୍ଟୋରୀ ଇଞ୍ଜିନ୍।",
    "as": "বিদ্যালয়, গৃহ নিৰ্মাণ সমিতি, চিকিৎসালয়, SaaS আৰু কৰ্পোৰেট প্ৰতিষ্ঠানৰ বাবে উপযোগী নিৰ্দেশিকা ইঞ্জিন।",
    "ur": "اسکولوں، ہاؤسنگ سوسائٹیز، ہسپتالوں، SaaS اور کارپوریٹ اداروں کے لیے موزوں ڈائرکٹری انجن۔",
    "ar": "محرك سجلات مرن قابل للتكيف مع المدارس والجمعيات السكنية والمستشفيات وشركات SaaS مع حقول مخصصة.",
    "es": "Motor de directorio versátil adaptable a escuelas, condominios, hospitales, SaaS y corporaciones.",
    "fr": "Moteur d'annuaire polyvalent adapté aux écoles, résidences, hôpitaux, SaaS et entreprises.",
    "de": "Vielseitige Verzeichnis-Engine für Schulen, Wohnanlagen, Krankenhäuser, SaaS & Unternehmen.",
    "ja": "学校、集合住宅、病院、SaaS、一般企業に対応する拡張可能なマスター台帳エンジン。",
    "zh": "适用于学校、物业社区、医疗机构、SaaS及大型企业的可扩展往来主数据引擎。"
},
