  'Post customer funds received, apply across outstanding invoices or FY opening balances, and create double-entry GL ledger vouchers.': {
    "en": "Post customer funds received, apply across outstanding invoices or FY opening balances, and create double-entry GL ledger vouchers.",
    "hi": "प्राप्त ग्राहक धनराशि दर्ज करें, बकाया चालानों या वित्तीय वर्ष प्रारंभिक शेष पर लागू करें, और बहीखाता वाउचर बनाएं।",
    "bn": "প্রাপ্ত তহবিল পোস্ট করুন, বকেয়া চালান বা খোলার ব্যালেন্সে প্রয়োগ করুন এবং লেজার ভাউচার তৈরি করুন।",
    "te": "స్వీకరించిన నిధులను నమోదు చేయండి, బకాయి ఇన్వాయిస్‌లకు వర్తింపజేయండి మరియు లెడ్జర్ వోచర్‌లను సృష్టించండి.",
    "mr": "प्राप्त निधी पोस्ट करा, थकीत बिलांवर लागू करा आणि लेजर व्हाउचर तयार करा.",
    "ta": "பெறப்பட்ட நிதிகளைப் பதிவுசெய்து, நிலுவையில் உள்ள பில்களில் பொருத்தி, லெட்ஜர் வவுச்சர்களை உருவாக்கவும்.",
    "gu": "પ્રાપ્ત થયેલ ભંડોળ પોસ્ટ કરો, બાકી ઇનવોઇસ પર લાગુ કરો અને લેજર વાઉચર બનાવો.",
    "kn": "ಸ್ವೀಕರಿಸಿದ ಹಣವನ್ನು ಪೋಸ್ಟ್ ಮಾಡಿ, ಬಾಕಿ ಉಳಿದ ಬಿಲ್‌ಗಳಿಗೆ ಅನ್ವಯಿಸಿ ಮತ್ತು ಲೆಡ್ಜರ್ ವೋಚರ್‌ಗಳನ್ನು ರಚಿಸಿ.",
    "ml": "ലഭിച്ച ഫണ്ട് രേഖപ്പെടുത്തുക, കുടിശ്ശികയുള്ള ഇൻവോയ്സുകളിൽ പ്രയോഗിക്കുക, ലെഡ്ജർ വൗച്ചറുകൾ സൃഷ്ടിക്കുക.",
    "pa": "ਪ੍ਰਾਪਤ ਫੰਡ ਪੋਸਟ ਕਰੋ, ਬਕਾਇਆ ਬਿੱਲਾਂ 'ਤੇ ਲਾਗੂ ਕਰੋ ਅਤੇ ਲੇਜ਼ਰ ਵਾਊਚਰ ਬਣਾਓ।",
    "or": "ପ୍ରାପ୍ତ ପାଣ୍ଠି ପୋଷ୍ଟ କରନ୍ତୁ, ବକେୟା ବିଲ୍ ଉପରେ ଲାଗୁ କରନ୍ତୁ ଏବଂ ଲେଜର ଭାଉଚର ସୃଷ୍ଟି କରନ୍ତୁ।",
    "as": "প্ৰাপ্ত পুঁজি পঞ্জীয়ন কৰক, বাকী থকা চালানত প্ৰয়োগ কৰক আৰু লেজাৰ ভাউচাৰ সৃষ্টি কৰক।",
    "ur": "موصولہ فنڈز درج کریں، واجب الادا انوائسز پر لاگو کریں اور لیجر واؤچر بنائیں۔",
    "ar": "ترحيل أموال العملاء المستلمة وتطبيقها على الفواتير المعلقة وإنشاء قيود دفتر الأستاذ المزدوجة.",
    "es": "Contabilice los fondos recibidos, aplíquelos a facturas pendientes y genere comprobantes de diario.",
    "fr": "Comptabilisez les fonds reçus, appliquez-les aux factures impayées et créez des pièces comptables.",
    "de": "Erfassen Sie Zahlungseingänge, verrechnen Sie offene Posten und buchen Sie Buchungsbelege.",
    "ja": "受領した顧客資金を転記し、未払請求書や期首残高に充当して複式仕訳伝票を作成します。",
    "zh": "过账收到的客户款项，分摊至未结发票或期初余额，并生成复式总账凭证。"
},
