    te: 'డబుల్-ఎంట్రీ పోస్ట్ చేయబడిన లావాదేవీలు, మార్చలేని ఆడిట్ వోచర్లు మరియు అనుకూల ఖాతాల పట్టిక.',
    mr: 'दुहेरी नोंद व्यवहार, अपरिवर्तनीय ऑडिट व्हाउचर आणि व्यवसाय-विशिष्ट खात्यांची यादी.',
    ta: 'இரட்டைப் பதிவு பரிவர்த்தனைகள், மாற்ற முடியாத தணிக்கை வவுச்சர்கள் மற்றும் பிரத்யேக கணக்கு விளக்கப்படம்.',
    gu: 'ડબલ-એન્ટ્રી પોસ્ટ કરેલ વ્યવહારો, અપરિવર્તનીય ઑડિટ વાઉચર્સ અને કસ્ટમ ચાર્ટ ઑફ એકાઉન્ટ્સ.',
    kn: 'ಡಬಲ್-ಎಂಟ್ರಿ ವಹಿವಾಟುಗಳು, ಬದಲಾಯಿಸಲಾಗದ ಆಡಿಟ್ ವೋಚರ್‌ಗಳು ಮತ್ತು ಕಸ್ಟಮ್ ಖಾತೆಗಳ ಪಟ್ಟಿ.',
    ml: 'ഡബിൾ എൻട്രി ഇടപാടുകൾ, മാറ്റമില്ലാത്ത ഓഡിറ്റ് വൗച്ചറുകൾ, കസ്റ്റം ചാർട്ട് ഓഫ് അക്കൗണ്ട്സ്.',
    pa: 'ਡਬਲ-ਐਂਟਰੀ ਲੈਣ-ਦੇਣ, ਅਟੱਲ ਆਡਿਟ ਵਾਊਚਰ ਅਤੇ ਕਸਟਮ ਚਾਰਟ ਆਫ਼ ਅਕਾਊਂਟਸ।',
    or: 'ଡବଲ୍-ଏଣ୍ଟ୍ରି ପୋଷ୍ଟ ହୋଇଥିବା କାରବାର, ଅପରିବର୍ତ୍ତନୀୟ ଅଡିଟ୍ ଭାଉଚର୍ ଏବଂ କଷ୍ଟମ୍ ଚାର୍ଟ ଅଫ୍ ଆକାଉଣ୍ଟସ୍ |',
    as: 'ডাবল-এণ্ট্ৰি লেনদেনসমূহ, অপৰিৱৰ্তনীয় অডিট ভাউচাৰ আৰু উদ্যোগ-নিৰ্দিষ্ট একাউণ্ট তালিকা।',
    ur: 'ڈبل انٹری پوسٹ کردہ ٹرانزیکشنز، ناقابل تغیر آڈٹ واؤچرز اور مخصوص چارٹ آف اکاؤنٹس۔',
