    hi: 'पूर्व-भरी ग्राहक सूची और स्वचालित दोहरा-प्रविष्टि GL पोस्टिंग के साथ बकाया प्राप्य या ग्राहक अग्रिम शेष स्थापित करें।',
    bn: 'স্বয়ংক্রিয় ডাবল-এন্ট্রি জিএল পোস্টিং সহ বকেয়া দেনাদার বা অগ্রিম ক্রেডিট সেটআপ করুন।',
