    gu: 'સંપૂર્ણ નાણાકીય બાબતો અને પેટા-ખાતાવહી નિકાસ કરો અથવા સિસ્ટમ પુનઃસ્થાપિત કરો.',
    kn: 'ಸಂಪೂರ್ಣ ಕಂಪನಿ ಹಣಕಾಸು ವಿವರಗಳನ್ನು ರಫ್ತು ಮಾಡಿ ಅಥವಾ ಸಿಸ್ಟಮ್ ಅನ್ನು ಮರುಸ್ಥಾಪಿಸಿ.',
    ml: 'സമ്പൂർണ്ണ സാമ്പത്തിക വിവരങ്ങളും ഉപ-ലെഡ്ജറുകളും കയറ്റുമതി ചെയ്യുക അല്ലെങ്കിൽ പുനഃസ്ഥാപിക്കുക.',
    pa: 'ਪੂਰੇ ਵਿੱਤੀ ਅਤੇ ਸਬ-ਲੇਜ਼ਰ ਨਿਰਯਾਤ ਕਰੋ ਜਾਂ ਸਿਸਟਮ ਨੂੰ ਰੀਸਟੋਰ ਕਰੋ।',
