    "mr": "सानुकूल विशेषता त्वरित जोडा",
    "ta": "தனிப்பयன் பண்புக்கூறை விரைவாகச் சேர்க்கவும்",
    "gu": "કસ્ટમ એટ્રિબ્યુટ ઝડપથી ઉમેરો",
    "kn": "ಕಸ್ಟಮ್ ಗುಣಲಕ್ಷಣವನ್ನು ತ್ವರಿತವಾಗಿ ಸೇರಿಸಿ",
    "ml": "ഇഷ്ടാനുസൃത ആട്രിബ്യൂട്ട് വേഗത്തിൽ ചേർക്കുക",
    "pa": "ਕਸਟਮ ਵਿਸ਼ੇਸ਼ਤਾ ਤੁਰੰਤ ਸ਼ਾਮਲ ਕਰੋ",
    "or": "ଶୀଘ୍ର କଷ୍ଟମ୍ ବିଶେଷତା ଯୋଡନ୍ତୁ",
    "as": "কাষ্টম বৈশিষ্ট্য ক্ষিপ্ৰভাৱে যোগ কৰক",
    "ur": "اپنی مرضی کی خصوصیت فوری شامل کریں",
