  "Pre-configure line items, billing terms, tax rates, and GL accounts for one-click invoice generation.": {
    "en": "Pre-configure line items, billing terms, tax rates, and GL accounts for one-click invoice generation.",
    "hi": "एक-क्लिक चालान निर्माण के लिए लाइन आइटम, बिलिंग शर्तें, कर दरें और जीएल खाते पूर्व-कॉन्फ़िगर करें।",
    "bn": "এক-ক্লিক চালান তৈরির জন্য লাইন আইটেম, বিলিং শর্তাবলী, করের হার এবং জিএল অ্যাকাউন্ট পূর্ব-কনফিগার করুন।",
    "te": "ఒక-క్లిక్ ఇన్‌వాయిస్ జనరేషన్ కోసం లైన్ ఐటెమ్‌లు, బిల్లింగ్ నిబంధనలు, పన్ను రేట్లు మరియు GL ఖాతాలను ముందుగా కాన్ఫిగర్ చేయండి.",
    "mr": "एका-क्लिक इनव्हॉइस जनरेशनसाठी लाइन आयटम, बिलिंग अटी, कर दर आणि GL खाती पूर्व-कॉन्फिगर करा.",
    "ta": "ஒரே கிளிக்கில் விலைப்பட்டியல் உருவாக்க வரி உருப்படிகள், பில்லிங் விதிமுறைகள், வரி விகிதங்கள் மற்றும் GL கணக்குகளை முன்கூட்டியே கட்டமைக்கவும்.",
    "gu": "એક-ક્લિક ઇનવોઇસ જનરેશન માટે લાઇન આઇટમ્સ, બિલિંગ શરતો, ટેક્સ દર અને GL એકાઉન્ટ્સ પૂર્વ-રૂપરેખાંકિત કરો.",
    "kn": "ಒಂದು-ಕ್ಲಿಕ್ ಇನ್‌ವಾಯ್ಸ್ ಉತ್ಪಾದನೆಗಾಗಿ ಸಾಲಿನ ಐಟಂಗಳು, ಬಿಲ್ಲಿಂಗ್ ನಿಯಮಗಳು, ತೆರಿಗೆ ದರಗಳು ಮತ್ತು GL ಖಾತೆಗಳನ್ನು ಮೊದಲೇ ಕಾನ್ಫಿಗರ್ ಮಾಡಿ.",
    "ml": "ഒറ്റ ക്ലിക്ക് ഇൻവോയ്സ് നിർമ്മാണത്തിനായി ലൈൻ ഇനങ്ങൾ, ബില്ലിംഗ് നിബന്ധനകൾ, നികുതി നിരക്കുകൾ, GL അക്കൗണ്ടുകൾ എന്നിവ മുൻകൂട്ടി കോൺഫിഗർ ചെയ്യുക.",
    "pa": "ਇੱਕ-ਕਲਿੱਕ ਇਨਵੌਇਸ ਬਣਾਉਣ ਲਈ ਲਾਈਨ ਆਈਟਮਾਂ, ਬਿਲਿੰਗ ਸ਼ਰਤਾਂ, ਟੈਕਸ ਦਰਾਂ ਅਤੇ GL ਖਾਤਿਆਂ ਨੂੰ ਪਹਿਲਾਂ ਤੋਂ ਕੌਂਫਿਗਰ ਕਰੋ।",
    "or": "ଗୋଟିଏ କ୍ଲିକ୍ ଇନଭଏସ୍ ଉତ୍ପାଦନ ପାଇଁ ଲାଇନ୍ ଆଇଟମ୍, ବିଲିଂ ସର୍ତ୍ତ, ଟ୍ୟାକ୍ସ ହାର ଏବଂ GL ଆକାଉଣ୍ଟ୍ ପୂର୍ବରୁ ସେଟ୍ କରନ୍ତୁ।",
    "as": "একক-ক্লিক চালান প্ৰস্তুতিৰ বাবে লাইন আইটেম, বিলিং চৰ্ত, কৰৰ হাৰ আৰু GL একাউণ্ট পূৰ্ব-কনফিগাৰ কৰক।",
    "ur": "ایک کلک میں انوائس بنانے کے لیے آئٹمز، بلنگ کی شرائط، ٹیکس کی شرحیں اور GL اکاؤنٹس پہلے سے ترتیب دیں۔",
    "ar": "قم بالتهيئة المسبقة للبنود وشروط الفوترة ومعدلات الضرائب وحسابات الأستاذ لإنشاء الفواتير بنقرة واحدة.",
    "es": "Preconfigure partidas, términos de facturación, tasas impositivas y cuentas de mayor para generar facturas con un clic.",
    "fr": "Préconfigurez les lignes, conditions de facturation, taux de taxe et comptes généraux pour une génération de facture en un clic.",
    "de": "Vorkonfigurieren Sie Positionen, Zahlungsbedingungen, Steuersätze und Sachkonten für die 1-Klick-Rechnungserstellung.",
    "ja": "ワンクリックで請求書を生成できるよう、明細項目、支払条件、税率、勘定科目を事前構成します。",
    "zh": "预设明细项目、结算周期条款、税率与总账科目，实现一键秒级开票。"
  },
