  "Switch between entities in the top header to inspect localized rules:": {
    "en": "Switch between entities in the top header to inspect localized rules:",
    "hi": "स्थानीयकृत नियमों का निरीक्षण करने के लिए शीर्ष शीर्षलेख में संस्थाओं के बीच स्विच करें:",
    "bn": "স্থানীয় নিয়মগুলি পরীক্ষা করতে শীর্ষ হেডারে সত্ত্বাগুলির মধ্যে পরিবর্তন করুন:",
    "te": "స్థానికీకరించిన నియమాలను తనిఖీ చేయడానికి ఎగువ శీర్షికలో ఎంటిటీల మధ్య మారండి:",
    "mr": "स्थानिक नियमांची तपासणी करण्यासाठी शीर्ष शीर्षलेखातील घटकांमध्ये स्विच करा:",
    "ta": "உள்ளூர்மயமாக்கப்பட்ட விதிகளை ஆய்வு செய்ய மேல் தலைப்பில் உள்ள நிறுவனங்களுக்கு இடையே மாறவும்:",
    "gu": "સ્થાનિક નિયમોનું નિરીક્ષણ કરવા માટે ટોચના હેડરમાં એકમો વચ્ચે સ્વિચ કરો:",
    "kn": "ಸ್ಥಳೀಯ ನಿಯಮಗಳನ್ನು ಪರಿಶೀಲಿಸಲು ಮೇಲಿನ ಹೆಡರ್‌ನಲ್ಲಿರುವ ಘಟಕಗಳ ನಡುವೆ ಬದಲಿಸಿ:",
    "ml": "പ്രാദേശികവൽക്കരിച്ച നിയമങ്ങൾ പരിശോധിക്കാൻ മുകളിലെ ഹെഡറിലെ എന്റിറ്റികൾക്കിടയിൽ മാറുക:",
    "pa": "ਸਥਾਨਕ ਨਿਯਮਾਂ ਦੀ ਜਾਂਚ ਕਰਨ ਲਈ ਚੋਟੀ ਦੇ ਸਿਰਲੇਖ ਵਿੱਚ ਇਕਾਈਆਂ ਵਿਚਕਾਰ ਸਵਿਚ ਕਰੋ:",
    "or": "ସ୍ଥାନୀୟ ନିୟମ ଯାଞ୍ଚ କରିବାକୁ ଉପର ହେଡର୍‌ରେ ଏଣ୍ଟିଟି ମଧ୍ୟରେ ସୁଇଚ୍ କରନ୍ତୁ:",
    "as": "স্থানীয় নিয়মসমূহ পৰীক্ষা কৰিবলৈ শীৰ্ষ হেডাৰত প্ৰতিষ্ঠানসমূহৰ মাজত পৰিৱৰ্তন কৰক:",
    "ur": "مقامی قواعد کا معائنہ کرنے کے لیے اوپر والے ہیڈر میں اداروں کے درمیان سوئچ کریں:",
    "ar": "قم بالتبديل بين الكيانات في الشريط العلوي لمعاينة القواعد المحلية:",
    "es": "Cambie entre entidades en el encabezado superior para inspeccionar las reglas localizadas:",
    "fr": "Basculez entre les entités dans l'en-tête supérieur pour inspecter les règles localisées :",
    "de": "Wechseln Sie in der oberen Leiste zwischen Entitäten, um lokalisierte Regeln einzusehen:",
    "ja": "上部ヘッダーで事業体を切り替えて、各国・地域の税制・法規制ルールを確認できます:",
    "zh": "在顶部法人主体切换器中选择对应实体，即可查看该法域的合规报表规则:"
  },
