  "No products or services found matching current filters. Click \"Add Product / Service\" or \"Load Industry Presets\" to populate your catalog.": {
      "hi": "वर्तमान फ़िल्टर से मेल खाने वाले कोई उत्पाद या सेवाएँ नहीं मिलीं। अपनी सूची भरने के लिए \"उत्पाद / सेवा जोड़ें\" या \"उद्योग प्रीसेट लोड करें\" पर क्लिक करें।",
      "bn": "বর্তমান ফিল্টারের সাথে মিলে এমন কোনো পণ্য বা পরিষেবা পাওয়া যায়নি। আপনার ক্যাটালগ পূরণ করতে \"পণ্য / পরিষেবা যোগ করুন\" বা \"শিল্প প্রিসেট লোড করুন\" ক্লিক করুন।",
      "te": "ప్రస్తుత ఫిల్టర్‌లకు సరిపోయే ఉత్పత్తులు లేదా సేవలు ఏవీ కనుగొనబడలేదు. మీ కేటలాగ్‌ను పూరించడానికి \"ఉత్పత్తి / సేవను జోడించండి\" లేదా \"పరిశ్రమ ప్రీసెట్‌లను లోడ్ చేయండి\" క్లిక్ చేయండి.",
      "mr": "वर्तमान फिल्टरशी जुळणारे कोणतेही उत्पादन किंवा सेवा आढळली नाही. तुमची कॅटलॉग भरण्यासाठी \"उत्पादन / सेवा जोडा\" किंवा \"उद्योग प्रीसेट लोड करा\" वर क्लिक करा.",
      "ta": "தற்போதைய வடிப்பான்களுடன் பொருந்தக்கூடிய தயாரிப்புகள் அல்லது சேவைகள் எதுவும் கிடைக்கவில்லை. உங்கள் அட்டவணையை நிரப்ப \"தயாரிப்பு / சேவையைச் சேர்க்கவும்\" அல்லது \"தொழில்துறை முன்னமைவுகளை ஏற்றவும்\" என்பதைக் கிளிக் செய்யவும்.",
      "gu": "વર્તમાન ફિલ્ટર્સ સાથે મેળ ખાતા કોઈ ઉત્પાદનો અથવા સેવાઓ મળી નથી. તમારી સૂચિ ભરવા માટે \"ઉત્પાદન / સેવા ઉમેરો\" અથવા \"ઉદ્યોગ પ્રીસેટ્સ લોડ કરો\" પર ક્લિક કરો.",
      "kn": "ಪ್ರಸ್ತುತ ಫಿಲ್ಟರ್‌ಗಳಿಗೆ ಹೊಂದಿಕೆಯಾಗುವ ಯಾವುದೇ ಉತ್ಪನ್ನಗಳು ಅಥವಾ ಸೇವೆಗಳು ಕಂಡುಬಂದಿಲ್ಲ. ನಿಮ್ಮ ಕ್ಯಾಟಲಾಗ್ ಅನ್ನು ಜನಪ್ರಿಯಗೊಳಿಸಲು \"ಉತ್ಪನ್ನ / ಸೇವೆಯನ್ನು ಸೇರಿಸಿ\" ಅಥವಾ \"ಉದ್ಯಮ ಪೂರ್ವನಿಗದಿಗಳನ್ನು ಲೋಡ್ ಮಾಡಿ\" ಕ್ಲಿಕ್ ಮಾಡಿ.",
      "ml": "നിലവിലെ ഫിൽട്ടറുകളുമായി പൊരുത്തപ്പെടുന്ന ഉൽപ്പന്നങ്ങളോ സേവനങ്ങളോ കണ്ടെത്തിയില്ല.",
      "pa": "ਮੌਜੂਦਾ ਫਿਲਟਰਾਂ ਨਾਲ ਮੇਲ ਖਾਂਦਾ ਕੋਈ ਉਤਪਾਦ ਜਾਂ ਸੇਵਾ ਨਹੀਂ ਮਿਲੀ। ਆਪਣੀ ਕੈਟਾਲਾਗ ਭਰਨ ਲਈ \"ਉਤਪਾਦ / ਸੇਵਾ ਸ਼ਾਮਲ ਕਰੋ\" ਜਾਂ \"ਉਦਯੋਗ ਪ੍ਰੀਸੈੱਟ ਲੋਡ ਕਰੋ\" ਤੇ ਕਲਿੱਕ ਕਰੋ।",
      "or": "ବର୍ତ୍ତମାନର ଫିଲ୍ଟର୍ ସହିତ ମେଳ ଖାଉଥିବା କୌଣସି ଉତ୍ପାଦ କିମ୍ବା ସେବା ମିଳିଲା ନାହିଁ।",
      "as": "বৰ্তমানৰ ফিল্টাৰসমূহৰ সৈতে মিল থকা কোনো সামগ্ৰী বা সেৱা পোৱা নগ’ল।",
      "ur": "موجودہ فلٹرز سے مماثل کوئی پروڈکٹ یا سروس نہیں ملی۔",
      "ar": "لم يتم العثور على منتجات أو خدمات مطابقة للبحث. انقر فوق \"إضافة منتج / خدمة\" أو \"تحميل النماذج الجاهزة\".",
      "es": "No se encontraron productos o servicios. Haga clic en \"Agregar Producto / Servicio\" o \"Cargar Plantillas de Industria\".",
      "fr": "Aucun produit ou service trouvé. Cliquez sur \"Ajouter un Produit / Service\" ou \"Charger les Modèles\".",
      "de": "Keine passenden Produkte oder Dienstleistungen gefunden. Klicken Sie auf \"Hinzufügen\" oder \"Vorlagen laden\".",
      "ja": "条件に一致する品目が見つかりません。「品目・サービス新規登録」または「業界別プリセット」をクリックしてください。",
      "zh": "未检索到匹配的商品或劳务。请点击“新增商品/劳务”或“导入行业标准预置库”进行初始化。"
  },
