  "Update Catalog Price & Log Audit Reason": {
      "hi": "सूची मूल्य अपडेट करें और ऑडिट कारण दर्ज करें",
      "bn": "ক্যাটালগ মূল্য আপডেট করুন এবং অডিট কারণ নথিভুক্ত করুন",
      "te": "కేటలాగ్ ధరను నవీకరించండి & ఆడిట్ కారణాన్ని నమోదు చేయండి",
      "mr": "कॅटलॉग किंमत अपडेट करा आणि ऑडिट कारण नोंदवा",
      "ta": "அட்டவணை விலையைப் புதுப்பித்து தணிக்கை காரணத்தைப் பதிவு செய்யவும்",
      "gu": "સૂચિ ભાવ અપડેટ કરો અને ઓડિટ કારણ નોંધો",
      "kn": "ಕ್ಯಾಟಲಾಗ್ ಬೆಲೆಯನ್ನು ನವೀಕರಿಸಿ ಮತ್ತು ಆಡಿಟ್ ಕಾರಣವನ್ನು ದಾಖಲಿಸಿ",
      "ml": "കാറ്റലോഗ് വില പുതുക്കി ഓഡിറ്റ് കാരണം രേഖപ്പെടുത്തുക",
      "pa": "ਕੈਟਾਲਾਗ ਕੀਮਤ ਅੱਪਡੇਟ ਕਰੋ ਅਤੇ ਆਡਿਟ ਕਾਰਨ ਦਰਜ ਕਰੋ",
      "or": "କାଟାଲଗ୍ ମୂଲ୍ୟ ଅପଡେଟ୍ କରନ୍ତୁ ଏବଂ ଅଡିଟ୍ କାରଣ ଲଗ୍ କରନ୍ତୁ",
      "as": "তালিকাৰ মূল্য নবীকৰণ কৰক আৰু অডিট কাৰণ লিপিবদ্ধ কৰক",
      "ur": "کیٹلاگ کی قیمت اپ ڈیٹ کریں اور آڈٹ کی وجہ درج کریں",
      "ar": "تحديث سعر الكتالوج وتسجيل سبب التدقيق",
      "es": "Actualizar Precio del Catálogo y Registrar Motivo de Auditoría",
      "fr": "Mettre à Jour le Prix du Catalogue et Enregistrer le Motif d'Audit",
      "de": "Katalogpreis aktualisieren & Audit-Begründung protokollieren",
      "ja": "カタログ価格の更新および監査理由の記録",
      "zh": "更新目录定价并归档合规审计事由"
  },
  "Every price adjustment is permanently recorded in the immutable audit log for compliance.": {
      "hi": "अनुपालन के लिए प्रत्येक मूल्य समायोजन स्थायी रूप से अपरिवर्तनीय ऑडिट लॉग में दर्ज किया जाता है।",
      "bn": "সম্মতির জন্য প্রতিটি মূল্য সমন্বয় স্থায়ীভাবে অপরিবর্তনীয় অডিট লগে নথিভুক্ত করা হয়।",
      "te": "సమ్మతి కోసం ప్రతి ధర సర్దుబాటు శాశ్వతంగా మార్చలేని ఆడిట్ లాగ్‌లో నమోదు చేయబడుతుంది.",
      "mr": "अनुपालनासाठी प्रत्येक किंमत बदल अपरिवर्तनीय ऑडिट नोंदीमध्ये कायमचा नोंदवला जातो.",
      "ta": "இணக்கத்திற்காக ஒவ்வொரு விலை மாற்றமும் மாற்ற முடியாத தணிக்கைப் பதிவில் நிரந்தரமாகப் பதிவு செய்யப்படுகிறது.",
      "gu": "અનુપાલન માટે દરેક ભાવ ગોઠવણ કાયમી ધોરણે અપરિવર્તનશીલ ઓડિટ લોગમાં નોંધવામાં આવે છે.",
      "kn": "ಅನುಸರಣೆಗಾಗಿ ಪ್ರತಿ ಬೆಲೆ ಹೊಂದಾಣಿಕೆಯನ್ನು ಬದಲಾಯಿಸಲಾಗದ ಆಡಿಟ್ ಲಾಗ್‌ನಲ್ಲಿ ಶಾಶ್ವತವಾಗಿ ದಾಖಲಿಸಲಾಗುತ್ತದೆ.",
      "ml": "എല്ലാ വില മാറ്റങ്ങളും സ്ഥിരമായി മാറ്റമില്ലാത്ത ഓഡിറ്റ് ലോഗിൽ രേഖപ്പെടുത്തുന്നു.",
      "pa": "ਪਾਲਣਾ ਲਈ ਹਰੇਕ ਕੀਮਤ ਵਿਵਸਥਾ ਨੂੰ ਸਥਾਈ ਤੌਰ 'ਤੇ ਅਟੱਲ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
      "or": "ଅନୁପାଳନ ପାଇଁ ପ୍ରତ୍ୟେକ ମୂଲ୍ୟ ପରିବର୍ତ୍ତନ ସ୍ଥାୟୀ ଭାବରେ ଅପରିବର୍ତ୍ତନୀୟ ଅଡିଟ୍ ଲଗ୍ ରେ ରେକର୍ଡ ହୁଏ।",
      "as": "অনুপালনৰ বাবে প্ৰতিটো মূল্য সালসলনি স্থায়ীভাৱে অপৰিৱৰ্তনীয় অডিট লগত লিপিবদ্ধ কৰা হয়।",
      "ur": "تعمیل کے لیے قیمتوں کی ہر ایڈجسٹمنٹ کو مستقل طور پر غیر متغیر آڈٹ لاگ میں ریکارڈ کیا جاتا ہے۔",
      "ar": "يتم تسجيل كل تعديل في الأسعار بشكل دائم في سجل التدقيق غير القابل للتعديل لأغراض الامتثال.",
      "es": "Cada ajuste de precio se registra permanentemente en el registro inmutable para cumplimiento.",
      "fr": "Chaque ajustement de prix est enregistré de manière permanente dans le journal inaltérable.",
      "de": "Jede Preisanpassung wird zur Compliance dauerhaft im unveränderlichen Audit-Protokoll gespeichert.",
      "ja": "コンプライアンス順守のため、すべての価格改定は改ざん不能な監査ログに永続記録されます。",
      "zh": "每一笔调价操作均会永久记入不可篡改的内控审计日志以满足法务与财税合规要求。"
  },
