  "Configure catalog codes, default prices, and tax rates for automatic invoicing.": {
      "hi": "स्वचालित चालान के लिए सूची कोड, डिफ़ॉल्ट मूल्य और कर दरें कॉन्फ़िगर करें।",
      "bn": "স্বয়ংক্রিয় চালানের জন্য ক্যাটালগ কোড, ডিফল্ট মূল্য এবং করের হার কনফিগার করুন।",
      "te": "స్వయంచాలక ఇన్‌వాయిసింగ్ కోసం కేటలాగ్ కోడ్‌లు, డిఫాల్ట్ ధరలు మరియు పన్ను రేట్లను కాన్ఫిగర్ చేయండి.",
      "mr": "स्वयंचलित बीजक तयार करण्यासाठी कॅटलॉग कोड, डीफॉल्ट किंमती आणि कर दर कॉन्फिगर करा.",
      "ta": "தானியங்கி விலைப்பட்டியலுக்கு அட்டவணை குறியீடுகள், இயல்புநிலை விலைகள் மற்றும் வரி விகிதங்களை உள்ளமைக்கவும்.",
      "gu": "સ્વચાલિત ઇન્વૉઇસિંગ માટે સૂચિ કોડ્સ, મૂળભૂત ભાવો અને કર દરો ગોઠવો.",
      "kn": "ಸ್ವಯಂಚಾಲಿತ ಇನ್‌ವಾಯ್ಸಿಂಗ್‌ಗಾಗಿ ಕ್ಯಾಟಲಾಗ್ ಕೋಡ್‌ಗಳು, ಡೀಫಾಲ್ಟ್ ಬೆಲೆಗಳು ಮತ್ತು ತೆರಿಗೆ ದರಗಳನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಿ.",
      "ml": "ഓട്ടോമാറ്റിക് ഇൻവോയ്സിംഗിനായി കാറ്റലോഗ് കോഡുകൾ, സ്ഥിരസ്ഥിതി വിലകൾ, നികുതി നിരക്കുകൾ എന്നിവ ക്രമീകരിക്കുക.",
      "pa": "ਆਟੋਮੈਟਿਕ ਇਨਵੌਇਸਿੰਗ ਲਈ ਕੈਟਾਲਾਗ ਕੋਡ, ਡਿਫੌਲਟ ਕੀਮਤਾਂ ਅਤੇ ਟੈਕਸ ਦਰਾਂ ਨੂੰ ਕੌਂਫਿਗਰ ਕਰੋ।",
      "or": "ସ୍ୱୟଂଚାଳିତ ଇନଭଏସିଂ ପାଇଁ କାଟାଲଗ୍ କୋଡ୍, ଡିଫଲ୍ଟ ମୂଲ୍ୟ ଏବଂ ଟିକସ ହାର କନଫିଗର୍ କରନ୍ତୁ।",
      "as": "স্বয়ংক্ৰিয় চালান সৃষ্টিৰ বাবে তালিকা ক’ড, ডিফল্ট মূল্য আৰু কৰৰ হাৰ সংৰಚনা কৰক।",
      "ur": "خودکار انوائسنگ کے لیے کیٹلاگ کوڈز، ڈیفالٹ قیمتیں اور ٹیکس کی شرحیں تشکیل دیں۔",
      "ar": "تهيئة رموز الكتالوج والأسعار الافتراضية ونسب الضرائب للفواتير التلقائية.",
      "es": "Configure códigos, precios predeterminados y tasas de impuestos para facturación automática.",
      "fr": "Configurez les codes, tarifs par défaut et taxes pour la facturation automatique.",
      "de": "Katalogcodes, Standardpreise und Steuersätze für die automatische Rechnungsstellung konfigurieren.",
      "ja": "自動請求処理のための品目コード・標準単価・適用税率の設定。",
      "zh": "配置品目编码、默认销售单价及适用税率以支持智能自动计费。"
  },
