      "kn": "ಪ್ರತಿ ಚದರ ಅಡಿಗೆ ನಿರ್ವಹಣಾ ಶುಲ್ಕ, ಪಾರ್ಕಿಂಗ್ ಶುಲ್ಕಗಳು, ಬ್ಯಾಂಕ್ವೆಟ್ ಹಾಲ್ ಬುಕಿಂಗ್, EV ಚಾರ್ಜಿಂಗ್.",
