  "I confirm this price revision is deliberate and complies with the tenant\\'s pricing policy and customer notification terms.": {
      "hi": "मैं पुष्टि करता हूं कि यह मूल्य संशोधन जानबूझकर है और किरायेदार की मूल्य निर्धारण नीति और ग्राहक अधिसूचना शर्तों का अनुपालन करता है।",
      "bn": "আমি নিশ্চিত করছি যে এই মূল্য সংশোধন উদ্দেশ্যপ্রণোদিত এবং প্রতিষ্ঠানের মূল্য নির্ধারণ নীতি ও শর্তাবলী মেনে চলে।",
      "te": "ఈ ధర సవరణ ఉద్దేశపూర్వకమైనదని మరియు సంస్థ యొక్క ధరల విధానానికి అనుగుణంగా ఉందని నేను ధృవీకరిస్తున్నాను.",
      "mr": "मी पुष्टी करतो की हा किंमत बदल जाणूनबुजून आहे आणि संस्थेच्या किंमत धोरणाचे पालन करतो.",
      "ta": "இந்த விலை திருத்தம் நிறுவனத்தின் விலைக் கொள்கைக்கு இணங்குகிறது என்பதை நான் உறுதிப்படுத்துகிறேன்.",
      "gu": "હું પુષ્ટિ કરું છું કે આ ભાવ સુધારો સંસ્થાની નીતિઓનું પાલન કરે છે.",
      "kn": "ಈ ಬೆಲೆ ಪರಿಷ್ಕರಣೆಯು ಉದ್ದೇಶಪೂರ್ವಕವಾಗಿದೆ ಮತ್ತು ಸಂಸ್ಥೆಯ ಬೆಲೆ ನೀತಿಗೆ ಬದ್ಧವಾಗಿದೆ ಎಂದು ನಾನು ಖಚಿತಪಡಿಸುತ್ತೇನೆ.",
      "ml": "ഈ വില പുനരവലോകനം സ്ഥാപനത്തിന്റെ വിലനിർണ്ണയ നയങ്ങൾക്ക് അനുസൃതമാണെന്ന് ഞാൻ സ്ഥിരീകരിക്കുന്നു.",
      "pa": "ਮੈਂ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹਾਂ ਕਿ ਇਹ ਕੀਮਤ ਸੋਧ ਜਾਣਬੁੱਝ ਕੇ ਕੀਤੀ ਗਈ ਹੈ ਅਤੇ ਸੰਸਥਾ ਦੀ ਕੀਮਤ ਨੀਤੀ ਦੀ ਪਾਲਣਾ ਕਰਦੀ ਹੈ।",
      "or": "ମୁଁ ନିଶ୍ଚିତ କରୁଛି ଯେ ଏହି ମୂଲ୍ୟ ସଂଶୋଧନ ନିୟମାନୁଯାୟୀ ହୋଇଛି।",
      "as": "মই নিশ্চিত কৰিছো যে এই মূল্য সংশোধন প্ৰতিষ্ঠানৰ মূল্য নিৰ্ধাৰণ নীতিৰ অনুসাৰে হৈছে।",
      "ur": "میں تصدیق کرتا ہوں کہ قیمت میں یہ نظر ثانی پالیسیوں کے عین مطابق ہے۔",
      "ar": "أقر بأن هذا التعديل في السعر معتمد ويتوافق مع سياسة التسعير وشروط إخطار العملاء.",
      "es": "Confirmo que esta revisión de precios es deliberada y cumple con la política de precios.",
      "fr": "Je confirme que cette révision de prix est délibérée et conforme à la politique tarifaire.",
      "de": "Ich bestätige, dass diese Preisänderung beabsichtigt ist und den Preisrichtlinien entspricht.",
      "ja": "この価格改定が承認済みであり、価格設定ポリシーおよび顧客通知条項に準拠していることを確認します。",
      "zh": "本人确认此调价行为已获正式核准，且符合商户定价政策及客户预先告知合规条款。"
  },
